`timescale 1ns/1ps
// tb_chain.v - host model for the BOUND chain simulation (Verilator --timing).
// The stimulus (stim.vh, generated by run_chain.py) calls wait_until/tx/set_temp;
// every byte received on FPGA1.RO is logged as "R <ns> <hex>" in rx.log.
module tb_chain;
    parameter integer N = 3, NCORE = 2, AW = 6, RDLAT = 1, BM2 = 0, MULLAT = 2, CPB = 8;
    localparam integer BIT_NS = CPB * 10;
    reg clk_ctl = 0, clk_hash = 0, locked = 0, host_tx = 1;
    always #5 clk_ctl = ~clk_ctl;
    always #2 clk_hash = ~clk_hash;
    reg  [12*N-1:0] temps;
    wire host_rx;
    wire [N-1:0] hashing;
    chain_top #(.N(N), .NCORE(NCORE), .AW(AW), .RDLAT(RDLAT), .BM2(BM2), .MULLAT(MULLAT), .CLKS_PER_BIT(CPB)) dut (
        .clk_ctl(clk_ctl), .clk_hash(clk_hash), .locked(locked), .host_tx(host_tx),
        .host_rx(host_rx), .temps(temps), .hashing(hashing));

    integer k;
    initial begin
        for (k = 0; k < N; k = k + 1) temps[12*k +: 12] = 12'd2626;   // ~50 C
        #200 locked = 1;
    end

    task wait_until(input integer t); begin if ($time < t) #(t - $time); end endtask
    task tx(input [7:0] b);
        integer i;
        begin
            host_tx = 0; #(BIT_NS);
            for (i = 0; i < 8; i = i + 1) begin host_tx = b[i]; #(BIT_NS); end
            host_tx = 1; #(BIT_NS);
        end
    endtask
    task set_temp(input integer f, input integer code); begin temps[12*f +: 12] = code; end endtask

    // receiver
    integer fd;
    reg [7:0] rb; integer j;
    initial begin
        fd = $fopen("rx.log", "w");
        forever begin
            @(negedge host_rx);
            #(BIT_NS + BIT_NS / 2);
            for (j = 0; j < 8; j = j + 1) begin rb[j] = host_rx; #(BIT_NS); end
            $fdisplay(fd, "R %0d %02x", $time, rb);
            $fflush(fd);
        end
    end

    initial begin
`include "stim.vh"
        $fclose(fd);
        $finish;
    end
endmodule
